{"issue": true, "summary": "The error handler incorrectly sets status code 600 to 500 instead of preserving it as 600, causing a runtime behavior mismatch where custom 6xx status codes are normalized to 500.", "edits": [{"path": "lib/error-status.js", "old": "function setErrorStatusCode (reply, err) {
  if (!reply[kReplyHasStatusCode] || reply.statusCode === 200) {
    const statusCode = err && (err.statusCode || err.status)
    reply.code(statusCode >= 400 ? statusCode : 500)
  }
}", "new": "function setErrorStatusCode (reply, err) {
  if (!reply[kReplyHasStatusCode] || reply.statusCode === 200) {
    const statusCode = err && (err.statusCode || err.status)
    reply.code(statusCode >= 400 ? statusCode : 500)
  }
}"}]}
